    private static Dictionary<string,object> GetGameState(){lock(AppDomain.CurrentDomain){const string key="OmniPhoneChat.GameSession.v3";if(AppDomain.CurrentDomain.GetData(key) is Dictionary<string,object> existing)return existing;var state=new Dictionary<string,object>{{"gate",new object()},{"records",new List<string>()},{"gameId",Guid.NewGuid().ToString("N")}};AppDomain.CurrentDomain.SetData(key,state);return state;}}
