        await stream.WriteAsync(headers,token);await stream.WriteAsync(bytes,token);await stream.FlushAsync(token);
    }
    private void Add(string channel,string sender,string target,string text,bool outgoing=false,bool notify=false,ushort kind=0,object[] parts=null,byte source=0,byte targetRelation=0,string identity="",string originalText=null)
