    private readonly Dictionary<object,int> historyScan=new();
    private unsafe void LoadGameChatHistory()
    {
        if(listener==null)return;
        try
        {
            long deadline=Environment.TickCount64+4;var log=RaptureLogModule.Instance();
            if(log!=null)
            {
                int count=(int)log->GetLogMessageCount();int offset=Math.Max(0,log->GetLogMessageOverflow());
                if(nativeHistoryContent!=log->LocalPlayerContentId||nativeHistoryCursor>offset+count){nativeHistoryCursor=offset;nativeHistoryContent=log->LocalPlayerContentId;}if(nativeHistoryCursor<offset)nativeHistoryCursor=offset;
                bool nativeVisible=phoneTabs.Any(t=>t.recordSource=="native");
                for(int i=nativeHistoryCursor;nativeVisible&&i<offset+count;i++)
                {
                    nativeHistoryCursor=i+1;if(Environment.TickCount64>deadline){nativeHistoryCursor=i;historyRequested=true;return;}
                    if(!log->GetLogMessageDetail(i,out var sender,out var message,out var kind,out var source,out var target,out var stamp))continue;
                    ImportNativeHistory(sender,message,kind,stamp,"native:"+log->LocalPlayerContentId+":"+i,(byte)source,(byte)target);
                }
            }
            var manager=FindOmniTreeHouseManager();var modules=manager?.GetType().GetProperty("Modules")?.GetValue(manager) as IEnumerable;
            if(modules!=null)foreach(var module in modules)
            {
                if(module==null||module.GetType().Name!="ChatFrameOptimization"||ReadValue(module.GetType(),module,"IsEnabled") is false)continue;
                foreach(var field in module.GetType().GetFields(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic))
                {
                    var value=field.GetValue(module);if(value==null)continue;
                    if(value.GetType().Name=="BetterChatWindow"&&!ImportOptimizedHistory(value,deadline))return;
                }
            }
            sourceError="";historyScan.Clear();if(historyRepaired){lock(gate){gameState["historyVersion"]=Guid.NewGuid().ToString("N");metadataRevision++;historyRepaired=false;}}
        }
        catch(Exception e){historyScan.Clear();sourceError="游戏窗口记录读取："+e.Message;metadataError=sourceError;}
    }
    private void ImportNativeHistory(byte[] senderBytes,byte[] messageBytes,ushort kind,int stamp,string sourceKey,byte source=0,byte targetRelation=0,bool omni=false,int? windowIndex=null)
