    private bool ImportCachedCollection(IEnumerable collection,bool world,long deadline)
    {
        historyScan.TryGetValue(collection,out int cursor);if(cursor<0)return true;
        if(collection is ICollection counted&&counted.Count<cursor)cursor=0;
        int index=0;
        foreach(var item in collection) {
