            if(world)ImportWorldHistory(item);
            else {var row=item is DictionaryEntry pair?pair.Value:item?.GetType().GetProperty("Value")?.GetValue(item)??item;var cacheKey=item is DictionaryEntry entry?entry.Key:item?.GetType().GetProperty("Key")?.GetValue(item);ImportOptimizedRecord(row,0,cacheKey is int indexKey?indexKey:null,cacheKey is Guid guidKey?guidKey:null);}
            if(Environment.TickCount64>=deadline){historyScan[collection]=index;historyRequested=true;return false;}
        }
        historyScan[collection]=-1;return true;
    }
    private bool ImportOptimizedHistory(object window,long deadline)
    {
        bool found=false;
        foreach(var field in window.GetType().GetFields(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic))
        {
            var type=field.FieldType;if(!type.IsGenericType)continue;var definition=type.GetGenericTypeDefinition();var arguments=type.GetGenericArguments();
            if((definition!=typeof(SortedDictionary<,>)&&definition!=typeof(Dictionary<,>))||arguments.Length!=2||arguments[1].DeclaringType!=window.GetType()||(arguments[0]!=typeof(int)&&arguments[0]!=typeof(Guid)))continue;
