        }
        if(!found)throw new InvalidOperationException("Omni 窗口记录接口不匹配，未使用其他消息来源补录");
        return true;
    }
    private unsafe void ImportOptimizedRecord(object record,int depth,int? windowIndex=null,Guid? windowMessageId=null)
    {
        if(record==null||depth>2)return;
        if(record.GetType().Name=="OmniWorldChatMessage"){ImportWorldHistory(record,windowMessageId);return;}
        var fields=record.GetType().GetFields(BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).OrderBy(f=>f.MetadataToken).ToArray();
        var blobs=fields.Where(f=>f.FieldType==typeof(byte[])).Select(f=>(byte[])f.GetValue(record)).ToArray();var ints=fields.Where(f=>f.FieldType==typeof(int)).Select(f=>(int)f.GetValue(record)).ToArray();var kind=fields.FirstOrDefault(f=>f.FieldType==typeof(ushort));var relations=fields.Where(f=>f.FieldType==typeof(byte)).Select(f=>(byte)f.GetValue(record)).ToArray();
        if(blobs.Length==2&&ints.Length==2&&kind!=null)
        {
            ImportNativeHistory(blobs[0],blobs[1],(ushort)kind.GetValue(record),ints[1],"native:"+nativeHistoryContent+":"+ints[0],relations.Length>0?relations[0]:(byte)0,relations.Length>1?relations[1]:(byte)0,true,windowIndex);return;
        }
        foreach(var nested in fields)if(nested.FieldType.DeclaringType==record.GetType().DeclaringType||nested.FieldType.Name=="OmniWorldChatMessage")ImportOptimizedRecord(nested.GetValue(record),depth+1,windowIndex,windowMessageId);
    }

    private void OnSuppressedChat(IChatMessage message){historyRequested=true;ObserveRecruitmentFailure(message);MirrorNativeEvent(message);}
    private void OnChat(IChatMessage message)
    {ObserveRecruitmentFailure(message);MirrorNativeEvent(message);
        RecordSourceProof(message);
        var kind=message.LogKind;var text=message.Message.TextValue;var sender=(message.Sender?.TextValue??"").Trim();
        if(sender.Length==0)NotifyRequest(text);
        if(kind==XivChatType.TellIncoming&&(sender=="Omni"||sender.StartsWith("Omni@"))&&Regex.IsMatch(text,@"^有人在国服频道\s*[@＠]\s*了你[。！!\s]*$"))return;
        var hidden=Regex.Match(sender,@"^冒险者(\d+)已隐藏(?:@.*)?$");
        if(hidden.Success&&(kind==XivChatType.TellIncoming||kind==XivChatType.TellOutgoing))
        {if(kind==XivChatType.TellIncoming)Add("国服悄悄话",sender,hidden.Groups[1].Value,text,false,settings.ReceiveWorldWhisper);return;}
        var channel=Label(kind);if(channel==null)return;
        bool outgoing=kind==XivChatType.TellOutgoing||sender==(objects?.LocalPlayer?.Name.TextValue??"\0");
        // Native history qualifies every player name with the home world. Use the same
        // identity for live messages so importing their cached copy merges the same row.
        var playerPayload=message.Sender?.Payloads.OfType<Dalamud.Game.Text.SeStringHandling.Payloads.PlayerPayload>().FirstOrDefault();
        sender=NormalizePlayerName(sender,playerPayload?.World.Value.Name.ToString()??"");
        var originalSender=Dalamud.Game.Text.SeStringHandling.SeString.Parse(message.OriginalSender.Data.Span);
        var originalPayload=originalSender.Payloads.OfType<Dalamud.Game.Text.SeStringHandling.Payloads.PlayerPayload>().FirstOrDefault();
        var identity=originalPayload!=null?NormalizePlayerName(originalPayload.PlayerName,originalPayload.World.Value.Name.ToString()):originalSender.TextValue.Trim();
        outgoing=outgoing||identity.Split('@')[0]==(objects?.LocalPlayer?.Name.TextValue??"\0");
        string recipient=originalPayload!=null||channel=="悄悄话"?identity:"";
        Add(channel,sender,recipient,text,outgoing,channel=="悄悄话"&&!outgoing&&settings.ReceiveTell,(ushort)kind,FormatParts(message.Message,ChatColor(channel)),(byte)message.SourceKind,(byte)message.TargetKind,identity,message.OriginalMessage.ExtractText());
    }
    private unsafe void OnPrompt(AddonEvent _,AddonArgs args)
    {
        try{var addon=(AddonSelectYesno*)args.Addon.Address;if(addon==null||addon->PromptText==null)return;var value=addon->PromptText->GetText();if(value.HasValue)NotifyRequest(value.ToString()??"");}catch{}
